--
-- Master data (starting values for a new Head Office database)
--

SET search_path = public;

DO $sync$
DECLARE r record;
BEGIN
    FOR r IN
        SELECT c.table_name, c.column_name,
               pg_get_serial_sequence('public.' || quote_ident(c.table_name), c.column_name) AS seq
        FROM information_schema.columns c
        WHERE c.table_schema = 'public'
    LOOP
        IF r.seq IS NOT NULL THEN
            EXECUTE format('SELECT setval(%L, COALESCE((SELECT MAX(%I) FROM public.%I), 0) + 1, false)', r.seq, r.column_name, r.table_name);
        END IF;
    END LOOP;
END
$sync$;
VALUES ('G001', 'Gain Ledger', 5, 'GN', 'GN', 0, 0, 0, '', 0, 2, 0, 2, 0, 0, 0,1,0);
VALUES ('L001', 'Loss Ledger', 8, 'GN', 'GN', 0, 0, 0, '', 0, 2, 0, 2, 0, 0, 0,0,1);
VALUES ('IK001', 'In-Kind Ledger', 5, 'GN', 'GN', 0, 0, 0, '', 0, 2, 0, 2, 0, 1, 0,0,0);
VALUES ('DI001', 'Disposal Ledger', 8, 'GN', 'GN', 0, 0, 0, '',0, 2, 0, 2, 0, 0, 0, 0, 0,1);

--
-- Move ID sequences past the inserted master data
--
DO $sync$
DECLARE r record;
BEGIN
    FOR r IN
        SELECT c.table_name, c.column_name,
               pg_get_serial_sequence('public.' || quote_ident(c.table_name), c.column_name) AS seq
        FROM information_schema.columns c
        WHERE c.table_schema = 'public'
    LOOP
        IF r.seq IS NOT NULL THEN
            EXECUTE format('SELECT setval(%L, COALESCE((SELECT MAX(%I) FROM public.%I), 0) + 1, false)', r.seq, r.column_name, r.table_name);
        END IF;
    END LOOP;
END
$sync$;
