-- Legal Entity - Society master statutory details and TAN list (26-Nov-2026); same as Sql/Upgrades/2026-11-26_legal_entity_society_master.sql
CREATE TABLE IF NOT EXISTS public.master_insti_statutory (
    "CUSTOMERID" integer NOT NULL,
    "ENTITY_TYPE" integer,
    "TRUST_DOC_NO" character varying(100) DEFAULT NULL::character varying,
    "BRANCH_INCHARGE" character varying(100) DEFAULT NULL::character varying,
    "PAN_STATUS" integer,
    "PAN_NAME" character varying(100) DEFAULT NULL::character varying,
    "PAN_REG_DATE" timestamp without time zone,
    "DARPAN_STATUS" integer,
    "DARPAN_ID" character varying(30) DEFAULT NULL::character varying,
    "DARPAN_REG_DATE" timestamp without time zone,
    "DARPAN_NAME" character varying(100) DEFAULT NULL::character varying,
    "A12_STATUS" integer,
    "A12_VALID_FROM" timestamp without time zone,
    "A12_VALID_TO" timestamp without time zone,
    "A12_NAME" character varying(100) DEFAULT NULL::character varying,
    "EIGHTYG_STATUS" integer,
    "EIGHTYG_VALID_FROM" timestamp without time zone,
    "EIGHTYG_VALID_TO" timestamp without time zone,
    "EIGHTYG_NAME" character varying(100) DEFAULT NULL::character varying,
    "FCRA_STATUS" integer,
    "FCRA_VALID_FROM" timestamp without time zone,
    "FCRA_VALID_TO" timestamp without time zone,
    CONSTRAINT master_insti_statutory_pkey PRIMARY KEY ("CUSTOMERID"),
    CONSTRAINT master_insti_statutory_customer_fk FOREIGN KEY ("CUSTOMERID")
        REFERENCES public.master_insti_perference ("CUSTOMERID") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.master_insti_tan (
    "TAN_ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "CUSTOMERID" integer NOT NULL,
    "TAN_NO" character varying(10) NOT NULL,
    "TAN_REG_DATE" timestamp without time zone,
    "TAN_NAME" character varying(100) DEFAULT NULL::character varying,
    CONSTRAINT master_insti_tan_pkey PRIMARY KEY ("TAN_ID"),
    CONSTRAINT master_insti_tan_customer_fk FOREIGN KEY ("CUSTOMERID")
        REFERENCES public.master_insti_perference ("CUSTOMERID") ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS master_insti_tan_unique_customer_tan
    ON public.master_insti_tan USING btree ("CUSTOMERID", "TAN_NO");

-- 2026-11-26 Project Mapping (per-branch project details)
CREATE TABLE IF NOT EXISTS public.project_branch_mapping (
    "PROJECT_BRANCH_MAP_ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "PROJECT_ID" integer NOT NULL,
    "BRANCH_ID" integer NOT NULL,
    "LOCATION_ID" integer NOT NULL,
    "CUSTOMERID" integer NOT NULL,
    "PROJECT_CATEGORY_ID" integer NOT NULL,
    "DIVISION_ID" integer NOT NULL,
    "DATE_STARTED" timestamp without time zone NOT NULL,
    "DATE_CLOSED" timestamp without time zone,
    "USER_ID" integer,
    "CREATED_DATE" timestamp without time zone DEFAULT now(),
    "MODIFIED_DATE" timestamp without time zone,
    CONSTRAINT project_branch_mapping_pkey PRIMARY KEY ("PROJECT_BRANCH_MAP_ID"),
    CONSTRAINT project_branch_mapping_project_fk FOREIGN KEY ("PROJECT_ID") REFERENCES public.master_project ("PROJECT_ID") ON DELETE CASCADE,
    CONSTRAINT project_branch_mapping_branch_fk FOREIGN KEY ("BRANCH_ID") REFERENCES public.branch_office ("BRANCH_OFFICE_ID"),
    CONSTRAINT project_branch_mapping_location_fk FOREIGN KEY ("LOCATION_ID") REFERENCES public.branch_location ("LOCATION_ID"),
    CONSTRAINT project_branch_mapping_society_fk FOREIGN KEY ("CUSTOMERID") REFERENCES public.master_insti_perference ("CUSTOMERID"),
    CONSTRAINT project_branch_mapping_category_fk FOREIGN KEY ("PROJECT_CATEGORY_ID") REFERENCES public.master_project_catogory ("PROJECT_CATOGORY_ID"),
    CONSTRAINT project_branch_mapping_division_fk FOREIGN KEY ("DIVISION_ID") REFERENCES public.master_division ("DIVISION_ID"),
    CONSTRAINT project_branch_mapping_user_fk FOREIGN KEY ("USER_ID") REFERENCES public.user_info ("USER_ID")
);
CREATE UNIQUE INDEX IF NOT EXISTS project_branch_mapping_unique_project_branch ON public.project_branch_mapping USING btree ("PROJECT_ID", "BRANCH_ID");
